using namespace std;

long long solve(vector<int>& arr) {
    int n = arr.size();

    // 计算所有元素的绝对值之和
    long long absSum = 0;
    for (int x : arr) {
        absSum += abs(x);
    }

    // 找到绝对值最小的元素
    int minAbs = INT_MAX;
    for (int x : arr) {
        minAbs = min(minAbs, abs(x));
    }

    // 统计负数的个数
    int negCount = 0;
    for (int x : arr) {
        if (x < 0) {
            negCount++;
        }
    }

    // 如果负数个数为偶数，所有数都可以为正
    // 如果负数个数为奇数，必须保留一个最小绝对值为负
    if (negCount % 2 == 0) {
        return absSum;
    } else {
        return absSum - 2LL * minAbs;
    }
}

